export function defaultCatalogImage(id: string, name?: string, icon?: string) {
  return (
    catalogArtwork[id] ??
    ((!icon || icon.trim() === '🛒') && name
      ? Object.entries(catalogArtworkAliases).find(
          ([alias]) => alias.toLowerCase() === name.trim().toLowerCase(),
        )?.[1]
      : undefined)
  )
}
